  // A native or intrinsic declaration has no emitted definition: its C++
  // surface lives in the shipped runtime headers and helper families. Each
  // of its MIR instances still carries a body — the verified boundary
  // shell — and once the shape is proven against the real body, the
  // absence of a definition IS that body's complete emission, so the
  // marker lands at the declaration site.
  void emitBoundaryDeclarationMarkers(const FunctionDecl &stmt) {
    if (mir == nullptr || !generalEmissionMap || emittingDeferredMember) {
      return;
    }
    const FunctionInfo *info = semantics.findFunction(stmt);
    if (info == nullptr || info->id == 0 || info->declaration != &stmt) {
      return;
    }
    const CppMirBodyEmitter &emitter = generalMirBodyEmitter();
    for (const MirFunctionInstance &instance : mir->functionInstances()) {
      if (instance.declaration != info->id ||
          instance.definitionKind ==
              MirFunctionInstance::DefinitionKind::Source) {
        continue;
      }
      if (!emitter.boundaryDeclarationBody(
              {.kind = MirBodyKind::Function, .owner = instance.id})) {
        throw std::logic_error(
            "production C++ emission has no verified-MIR boundary shell for "
            "function '" +
            stmt.name().lexeme + "'");
      }
      writeIndent();
      output << "// GTI verified-MIR body: native-boundary-v1 "
                "function-instance "
             << instance.id << "\n";
    }
  }

  void visitFunctionDecl(const FunctionDecl &stmt) override {
    emitBoundaryDeclarationMarkers(stmt);
    if (stmt.runtimeBinding() || isIntrinsicFunction(stmt)) {
      return;
    }
    const MirFunctionInstance *mirCfg = selectedMirScalarCfg(stmt);
    const MirFunctionInstance *mirBody = mirCfg;
    const MirFunctionInstance *mirGeneralFailure =
        selectedMirGeneralFailureFunction(stmt);
    const std::string callableTemplate =
        mirBody == nullptr && mirGeneralFailure == nullptr
            ? selectedMirCallableTemplateText(stmt)
            : std::string();
    const std::string callableFailureTemplate =
        mirBody == nullptr && mirGeneralFailure == nullptr &&
                callableTemplate.empty()
            ? selectedMirCallableTemplateFailureText(stmt)
            : std::string();
    const bool genericPrimarySurface =
        !stmt.genericParameters().empty() ||
        (currentClass != nullptr && !currentClass->genericParameters().empty());
    const bool declarationOnlyGenericPrimary =
        mir != nullptr && genericPrimarySurface && mirBody == nullptr &&
        mirGeneralFailure == nullptr && callableTemplate.empty() &&
        callableFailureTemplate.empty();
    if (declarationOnlyGenericPrimary && emittingDeferredMember) {
      // The in-class declaration is the primary. Closed-world concrete
      // instances are emitted below as verified-MIR specializations; an
      // out-of-class repetition would be neither a definition nor useful.
      return;
    }
    if (emittingDeferredMember && currentClass != nullptr) {
      emitTemplateDeclaration(currentClass->genericParameters());
    }
    emitTemplateDeclaration(stmt.genericParameters());
    writeIndent();
    if (mirGeneralFailure != nullptr) {
      emitGeneralFailureSignature(stmt, *mirGeneralFailure);
    } else if (!callableFailureTemplate.empty()) {
      // The may-raise deduced-callable template publishes its transformed
      // sibling under the template header; the wrapper template follows
      // the body.
      emitCallableTemplateFailureSignature(stmt);
    } else {
      // The deduced-callable template keeps the compat template header
      // and return type but names its parameters for the MIR body text.
      emitFunctionSignature(stmt, mirBody, !callableTemplate.empty());
    }
    const FunctionInfo *info = semantics.findFunction(stmt);
    const bool interfaceContract =
        currentClass != nullptr && currentClass->kind() == ClassKind::Interface;
    if (stmt.isPure() || (info != nullptr && info->pureVirtual) ||
        interfaceContract) {
      output << " = 0;\n";
      emitVirtualFailureContractDeclaration(stmt);
      emitStructuralOperatorAdapter(stmt);
      return;
    }
    if (stmt.body()) {
      if (currentClass != nullptr && !emittingDeferredMember) {
        output << ";\n";
        if (mirGeneralFailure != nullptr) {
          // Source templates are parsed before GTI's concrete
          // monomorphizations are selected. A non-dependent member call in
          // an otherwise unused template therefore still needs the ordinary
          // source name to be declared. Deliberately publish no definition:
          // admitted calls use the transformed sibling, while any missed
          // ordinary call fails closed at native link instead of terminating
          // inside a compatibility wrapper and bypassing MIR cleanup.
          writeIndent();
          emitFunctionSignature(stmt, nullptr);
          output << ";\n";
        }
        if (currentClass != nullptr && info != nullptr &&
            anyMemberFailureSpecialization(stmt)) {
          // The owner surface declares each transformed sibling before a
          // caller can reference it. Generic owners publish explicit member
          // specializations; generic members of ordinary owners publish
          // concrete overloads.
          emitPrimaryTransformedMemberDeclaration(stmt, *info);
        }
        deferredMemberDefinitions.push_back(
            {.kind = DeferredMemberKind::Function,
             .owner = currentClass,
             .function = &stmt,
             .namespaceScope = sourceNamespaces});
        emitStructuralOperatorAdapter(stmt);
        emitCallableAdapter(stmt);
        return;
      }
      if (mirGeneralFailure != nullptr) {
        if (info != nullptr && info->entryKind != ProgramEntryKind::None) {
          ownedArgumentsEntry = &stmt;
          generalFailureEntry = mirGeneralFailure;
        }
        output << ' ';
        emitGeneralFailureBodyText(*mirGeneralFailure);
        if (emittingDeferredMember) {
          emitGeneralFailureVirtualBoundaryWrapper(stmt, *mirGeneralFailure);
        }
        const bool virtualBoundaryOwnsOrdinaryAbi =
            emittingDeferredMember && mirGeneralFailure->virtualMethod;
        if (mirCfg != nullptr && !virtualBoundaryOwnsOrdinaryAbi) {
          // The ordinary and transformed ABIs are additive. Each definition
          // comes from its independently admitted spelling of the same MIR
          // body; keeping the plain form prevents native helpers and
          // compatibility callers from resolving to a declaration-only
          // symbol while the transformed call graph remains available. A
          // virtual member's native ABI was already supplied by the boundary
          // wrapper above, so emitting this second definition would collide.
          writeIndent();
          emitFunctionSignature(stmt, mirCfg);
          output << ' ';
          emitMirScalarCfgBody(*mirCfg);
        }
        if (!emittingDeferredMember) {
          // Keep ordinary-name lookup available while source primary
          // templates coexist with transformed concrete instances. This is
          // deliberately declaration-only; no compatibility implementation
          // may terminate across an un-emitted MIR cleanup boundary.
          writeIndent();
          emitFunctionSignature(stmt, nullptr);
          output << ";\n";
          emitStructuralOperatorAdapter(stmt);
          emitCallableAdapter(stmt);
        }
        return;
      }
      if (mirBody != nullptr) {
        // The shipped program-entry adapter forwards to the emitted entry
        // body regardless of which route produced it.
        if (info != nullptr && info->entryKind != ProgramEntryKind::None) {
          ownedArgumentsEntry = &stmt;
        }
        output << ' ';
        emitMirScalarCfgBody(*mirCfg);
        if (!emittingDeferredMember) {
          emitStructuralOperatorAdapter(stmt);
          emitCallableAdapter(stmt);
        }
        return;
      }
      if (!callableFailureTemplate.empty()) {
        // The transformed sibling template body belongs to the closed
        // failure component; no ordinary-signature wrapper may terminate
        // inside the call graph.
        output << ' ' << callableFailureTemplate;
        if (!emittingDeferredMember) {
          emitStructuralOperatorAdapter(stmt);
          emitCallableAdapter(stmt);
          // Nameable class-callable instantiations can require a different
          // lifetime-slot shape from the lambda-primary body. Their concrete
          // transformed overloads are declared by the forward pass and are
          // defined alongside the primary template here.
          emitGeneralTemplateSpecializations(stmt, false);
        }
        return;
      }
      if (!callableTemplate.empty()) {
        // The deduced-callable template body: one verified text covering
        // every monomorphized instance, spelled under the declaration's
        // own template header and signature.
        output << ' ' << callableTemplate;
        if (!emittingDeferredMember) {
          emitStructuralOperatorAdapter(stmt);
          emitCallableAdapter(stmt);
        }
        return;
      }
      if (info != nullptr && info->entryKind != ProgramEntryKind::None) {
        ownedArgumentsEntry = &stmt;
      }
      if (declarationOnlyGenericPrimary) {
        output << ";\n";
        if (!emittingDeferredMember) {
          emitStructuralOperatorAdapter(stmt);
          emitCallableAdapter(stmt);
          emitGeneralTemplateSpecializations(stmt, false);
        }
        return;
      }
      rejectMissingMirBodyEmission("function", stmt.name().lexeme);
    } else {
      output << ";\n";
      emitStructuralOperatorAdapter(stmt);
    }
  }

